def native_catalog_content(path: Path) -> str:
    """Decode one canonical native artifact without reading generated output."""
    encoded = CATALOG_BASE64.get(path.as_posix())  # lup: ignore[dict-get]
    if encoded is None:
        raise FileNotFoundError(f"native catalog artifact is missing: {path}")
    return base64.b64decode(encoded).decode("utf-8")


def native_catalog_digest() -> str:
    """Hash every path and byte in the immutable native catalog."""
    digest = hashlib.sha256()
    for path, encoded in sorted(CATALOG_BASE64.items()):
        digest.update(path.encode("utf-8"))
        digest.update(b"\0")
        digest.update(base64.b64decode(encoded))
        digest.update(b"\0")
    return digest.hexdigest()
